/ @Component — class-level, auto-detected via @ComponentScan
@Component
public class EmailService {
    public String send(String to) {
        return "Email sent to " + to;
    }
}

// @Bean — method-level, inside a @Configuration class
@Configuration
public class AppConfig {
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
/ Usage via @Autowired
@Service
public class UserService {
    @Autowired private EmailService emailService;      // @Component
    @Autowired private PasswordEncoder passwordEncoder; // @Bean

    public void register(String email, String password) {
        String hash = passwordEncoder.encode(password);
        System.out.println("Hash: " + hash);
        System.out.println(emailService.send(email));
    }
}


2.
// Field Injection (not recommended — hides dependencies)
@Service
public class OrderService {
    @Autowired
    private PaymentService paymentService; // hidden dep
}

// Constructor Injection (recommended — immutable, testable)
@Service
public class OrderService {
    private final PaymentService paymentService;

    public OrderService(PaymentService paymentService) {
        this.paymentService = paymentService;
    }
public String placeOrder(double amount) {
        return paymentService.charge(amount);
    }
}

// Test without Spring context (impossible with field injection)
@Test
void testOrder() {
    PaymentService mock = new MockPaymentService();
    OrderService svc = new OrderService(mock);  // ✅ easy
    assertEquals("charged 99.0", svc.placeOrder(99.0));
}

